// Build one Apify call per platform from the inputs above.
const s = $input.first().json;
const calls = [];
const max = Number(s.maxItemsPerPlatform) || 20;
calls.push({ platform: 'Taobao/Tmall', actor: 'tubetext~taobao-tmall-scraper',
  input: { keywords: [s.taobaoKeyword || s.keyword], maxItemsPerQuery: max } });
calls.push({ platform: 'AliExpress', actor: 'tubetext~aliexpress-search-scraper',
  input: { keywords: [s.keyword], maxItemsPerKeyword: max, sortBy: 'orders', shipTo: s.shipTo || 'US', currency: 'USD', skipNewShopperDeals: true } });
const tts = (s.tiktokShopUrls || []).map(u => String(u).trim()).filter(Boolean);
if (tts.length) calls.push({ platform: 'TikTok Shop', actor: 'tubetext~tiktok-shop-product-scraper',
  input: { urls: tts, maxProductsPerListing: max } });
return calls.map(c => ({ json: c }));

// Turn all returned products into one comparison row per platform (prices in USD).
const s = $('Set your product idea').first().json;
const cnyPerUsd = Number(s.cnyPerUsd) || 7.1;
const platformOf = it => /taobao|tmall/i.test(it.url || '') ? 'Taobao/Tmall'
  : /aliexpress/i.test(it.url || '') ? 'AliExpress'
  : /tiktok/i.test(it.url || '') ? 'TikTok Shop' : null;
const usd = it => it.priceCNY != null ? it.priceCNY / cnyPerUsd : (typeof it.price === 'number' ? it.price : null);
const groups = {};
for (const { json: it } of $input.all()) {
  const p = platformOf(it);
  if (!p || it.status !== 'ok') continue;
  (groups[p] = groups[p] || []).push(it);
}
return Object.entries(groups).map(([platform, items]) => {
  const prices = items.map(usd).filter(x => x != null).sort((a, b) => a - b);
  const top = [...items].sort((a, b) => (b.soldCount || 0) - (a.soldCount || 0) || (usd(a) || 0) - (usd(b) || 0)).slice(0, 5);
  return { json: {
    platform,
    products: items.length,
    minPriceUSD: prices.length ? +prices[0].toFixed(2) : null,
    medianPriceUSD: prices.length ? +prices[Math.floor(prices.length / 2)].toFixed(2) : null,
    top5: top.map(it => `${(usd(it) ?? 0).toFixed(2)} USD | ${it.soldCount ? it.soldCount + ' sold | ' : ''}${(it.title || '').slice(0, 60)} | ${it.url}`).join('\n'),
  }};
});
